export const SUMMARY_VOICE_VERSION = 2;

export function summaryAudioRequest(endpoint, shareId, audioSrc) {
  const base = String(endpoint || '').replace(/\/+$/, '');
  if (!base) return null;
  // Saved audio is a site-owned immutable asset, never a new synthesis request.
  if (typeof audioSrc === 'string' && audioSrc.startsWith(`${base}/view-audio-assets/`)
    && /^[a-f0-9]{64}\.mp3$/.test(audioSrc.slice(`${base}/view-audio-assets/`.length))) {
    return { url: audioSrc, method: 'GET' };
  }
  return shareId ? { url: `${base}/view-audio/${encodeURIComponent(shareId)}`, method: 'POST' } : null;
}
